'use strict';

const os = require('os');
const _flattenDeep = require('lodash/flattenDeep');
const _merge = require('lodash/merge');
const format = require('pff');

const defaultLevel = 'info';
const defaultConfig = {
    name: 'yandex-logger',
    streams: [
        {
            level: defaultLevel,
            stream: require('../streams/default')(),
        },
    ],
    middleware: [
        require('../middleware/preset-default')(),
    ],
    fields: {},
};

const levels = {
    trace: 10,
    debug: 20,
    info: 30,
    warn: 40,
    error: 50,
    fatal: 60,
};

const levelNames = Object
    .keys(levels)
    .reduce((names, name) => {
        names[levels[name]] = name.toUpperCase();
        return names;
    }, {});

class YandexLogger {
    /**
     * @param {Object} [config]
     * @constructor
     */
    constructor(config) {
        config = Object.assign({}, defaultConfig, config);

        this._hostname = os.hostname();
        this._streams = this._prepareStreams(config.streams);
        this._minLogLevel = Math.min(...this._streams.map(stream => stream.level));
        this._middleware = _flattenDeep(config.middleware);
        this._fields = Object.assign({ name: config.name }, config.fields);
    }

    trace() {
        this._log(levels.trace, this._fromArgs(arguments));
    }

    debug() {
        this._log(levels.debug, this._fromArgs(arguments));
    }

    info() {
        this._log(levels.info, this._fromArgs(arguments));
    }

    warn() {
        this._log(levels.warn, this._fromArgs(arguments));
    }

    error() {
        this._log(levels.error, this._fromArgs(arguments));
    }

    fatal() {
        this._log(levels.fatal, this._fromArgs(arguments));
    }

    /**
     * @param {Object} [fields]
     * @returns {Logger}
     */
    child(fields) {
        let child = Object.create(this);
        child._fields = Object.assign({}, child._fields, fields);
        return child;
    }

    /**
     * @returns {Object}
     */
    getFields() {
        return this._fields;
    }

    /**
     * @param {Object} fields
     * @param {Boolean} [merge=false]
     * @returns {undefined}
     */
    extendFields(fields, merge = false) {
        if (merge) {
            _merge(this._fields, fields);
            return;
        }

        Object.assign(this._fields, fields);
    }

    /**
     * @param {Object} fields
     * @returns {undefined}
     */
    deepExtendFields(fields) {
        this.extendFields(fields, true);
    }

    /**
     * @param {Number} level
     * @param {Array} data
     * @returns {undefined}
     * @private
     */
    _log(level, data) {
        if (level < this._minLogLevel) {
            return;
        }
        let record = this._makeRecord(level, data);

        this._applyMiddleware(record, 0, () => {
            for (let stream of this._streams) {
                if (stream.level <= level) {
                    stream.writable.write(record);
                }
            }
        });
    }

    /**
     * @param {Object} streamsConfig
     * @param   {String=} streamsConfig[].level
     * @param   {Object} streamsConfig[].stream
     * @param   {Function} streamsConfig[].stream.write
     * @returns {Array<{level: Number, writable: {write: Function}}>}
     * @private
     */
    _prepareStreams(streamsConfig) {
        return streamsConfig.map(streamConfig => {
            if (!streamConfig || !this._isWritableStream(streamConfig.stream)) {
                throw new TypeError('Stream must be Writable');
            }

            return {
                level: levels[streamConfig.level || defaultLevel],
                writable: streamConfig.stream,
            };
        });
    }

    /**
     * @param {Object} [stream]
     * @returns {Boolean}
     * @private
     */
    _isWritableStream(stream) {
        return stream && typeof stream.write === 'function';
    }

    /**
     * @param {Object} record
     * @param {Number} [current=0]
     * @param {Function} [onFinish]
     * @returns {undefined}
     * @private
     */
    _applyMiddleware(record, current, onFinish) {
        current = current || 0;
        let fn = this._middleware[current];

        if (fn) {
            const next = () => this._applyMiddleware(record, current + 1, onFinish);

            if (fn.length > 1) {
                return fn(record, next);
            }

            fn(record);
            return next();
        }

        onFinish && onFinish();
    }

    /**
     * @param {Number} level
     * @param {Array} data
     * @returns {Object}
     * @private
     */
    _makeRecord(level, data) {
        let record = {
            pid: process.pid,
            date: new Date(),
            hostname: this._hostname,
            level,
            levelName: levelNames[level],
        };

        if (data[0] instanceof Error) {
            record.err = data[0];
        } else if (typeof data[0] === 'object') {
            Object.assign(record, data[0]);
        }

        let message = this._getMessage(data);
        record.msgFormat = message[0] || '';
        record.msgArgs = message.slice(1);

        if (record.msgArgs.length > 0) {
            record.msg = format.apply(null, message);
        } else {
            record.msg = record.msgFormat;
        }

        // Дополняем данными из this._fields, но не перетираем существующие свойства
        for (let key in this._fields) {
            if (!record.hasOwnProperty(key)) {
                record[key] = this._fields[key];
            }
        }

        return record;
    }

    /**
     * @param {Array} data
     * @returns {Array}
     * @private
     */
    _getMessage(data) {
        if (data[0] instanceof Error) {
            // logger(err)
            if (data.length === 1) {
                return [data[0].message];
            }

            // logger(err, message, ...args)
            return data.slice(1);
        }

        // logger(message, ...args)
        if (typeof data[0] !== 'object') {
            return data;
        }

        // logger({ err })
        if (data[0] && data.length === 1 && data[0].err && data[0].err instanceof Error) {
            return [data[0].err.message];
        }

        // logger({ err }, message, ...args)
        return data.slice(1);
    }

    /**
     * Максимально быстро преобразует arguments к массиву
     * @param {Object} args
     * @returns {Array}
     * @private
     */
    _fromArgs(args) {
        if (args.length === 0) {
            return [];
        }

        if (args.length === 1) {
            return [args[0]];
        }

        if (args.length === 2) {
            return [args[0], args[1]];
        }

        if (args.length === 3) {
            return [args[0], args[1], args[2]];
        }

        if (args.length === 4) {
            return [args[0], args[1], args[2], args[3]];
        }

        if (args.length === 5) {
            return [args[0], args[1], args[2], args[3], args[4]];
        }

        return Array.from(args);
    }
}

module.exports = config => new YandexLogger(config);
